insert into skill_lab_private.lessons(skill,module,version,content,published) values ('reading_true_false_not_given','reading',1,'{"skill":"reading_true_false_not_given","module":"reading","title":"False or Not Given?","outcome":"Separate contradiction from missing information.","trap":"Do not treat a missing detail as false.","strategy":"Check each part of the statement. Find support or a contradiction. If neither exists, choose Not Given.","example":"The shop opens at nine. → It opens at ten: False. It closes at six: Not Given.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"reading_true_false_not_given-0","kind":"choice","prompt":"The library closes later than before.","options":["True","False","Not Given"],"answer":"True","explanation":"The passage supports the statement: The library now closes at eight instead of six.","hint":"Compare every detail with the lesson strategy.","passage":"The library now closes at eight instead of six.","evidence":["The library now closes at eight instead of six.","Information absent"],"evidence_answer":"The library now closes at eight instead of six.","stage":"guided"},{"id":"reading_true_false_not_given-1","kind":"choice","prompt":"All diesel buses were replaced.","options":["False","Not Given","True"],"answer":"False","explanation":"The passage contradicts the statement: Electric buses replaced half the diesel fleet last year.","hint":"Compare every detail with the lesson strategy.","passage":"Electric buses replaced half the diesel fleet last year.","evidence":["Electric buses replaced half the diesel fleet last year.","Information absent"],"evidence_answer":"Electric buses replaced half the diesel fleet last year.","stage":"guided"},{"id":"reading_true_false_not_given-2","kind":"choice","prompt":"Online tickets cost less than tickets at the door.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"Museum visitors can book tickets online.","evidence":["Museum visitors can book tickets online.","Information absent"],"evidence_answer":"Information absent","stage":"guided"},{"id":"reading_true_false_not_given-3","kind":"choice","prompt":"Volunteers meet every Saturday.","options":["True","False","Not Given"],"answer":"False","explanation":"The passage contradicts the statement: Volunteers meet in the garden every second Saturday.","hint":"Compare every detail with the lesson strategy.","passage":"Volunteers meet in the garden every second Saturday.","evidence":["Volunteers meet in the garden every second Saturday.","Information absent"],"evidence_answer":"Volunteers meet in the garden every second Saturday.","stage":"guided"},{"id":"reading_true_false_not_given-4","kind":"choice","prompt":"The course begins in May.","options":["False","Not Given","True"],"answer":"True","explanation":"The passage supports the statement: The evening course runs for six weeks and starts in May.","hint":"Compare every detail with the lesson strategy.","passage":"The evening course runs for six weeks and starts in May.","evidence":["The evening course runs for six weeks and starts in May.","Information absent"],"evidence_answer":"The evening course runs for six weeks and starts in May.","stage":"independent"},{"id":"reading_true_false_not_given-5","kind":"choice","prompt":"The pool offers swimming lessons.","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"The pool is closed on Mondays for cleaning.","evidence":["The pool is closed on Mondays for cleaning.","Information absent"],"evidence_answer":"Information absent","stage":"independent"},{"id":"reading_true_false_not_given-6","kind":"choice","p