","options":["Not Given","True","False"],"answer":"Not Given","explanation":"The passage does not establish or contradict this detail. Missing information is not a contradiction.","hint":"Compare every detail with the lesson strategy.","passage":"The gallery displays paintings by regional artists.","evidence":["The gallery displays paintings by regional artists.","Information absent"],"evidence_answer":"Information absent","stage":"independent"}]}'::jsonb,true) on conflict(skill,version) do nothing;
insert into skill_lab_private.lessons(skill,module,version,content,published) values ('reading_paraphrase_matching','reading',1,'{"skill":"reading_paraphrase_matching","module":"reading","title":"Recognise the same meaning","outcome":"Match meaning even when the wording changes.","trap":"A shared word does not guarantee a shared meaning.","strategy":"Compare who, what, quantity and time. Reject an option that adds or reverses a detail.","example":"Reduced waiting time means a shorter wait, not a shorter journey.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"reading_paraphrase_matching-0","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["extended opening hours","the complete closure of the library","an increase in prices at the library"],"answer":"extended opening hours","explanation":"“extended opening hours” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"The library now closes at eight instead of six.","stage":"guided"},{"id":"reading_paraphrase_matching-1","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["the complete closure of the buses","an increase in prices at the buses","partial fleet replacement"],"answer":"partial fleet replacement","explanation":"“partial fleet replacement” preserves what the text states without adding a closure or a price change.","hint":"Compare every detail with the lesson strategy.","passage":"Electric buses replaced half the diesel fleet last year.","stage":"guided"},{"id":"reading_paraphrase_matching-2","kind":"choice","prompt":"Which phrase preserves the meaning?","options":["an increase in prices at the museum","online booking availability","the complete closure of the museum"],"answer":"online booking availability","explanation":"“online booking availability” preserves what the text states without adding a closure or a price change.","hint":"Compare 