insert into skill_lab_private.lessons(skill,module,version,content,published) values ('reading_matching_headings','reading',1,'{"skill":"reading_matching_headings","module":"reading","title":"Find the main idea","outcome":"Choose a heading covering the whole paragraph.","trap":"An example can distract from the main point.","strategy":"Summarise the paragraph in a few words, then compare the breadth of each heading.","example":"A paragraph explaining a move caused by flooding needs a heading about relocation, not ticket prices.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"reading_matching_headings-0","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["extended opening hours","The history of ticket prices","Plans for overseas expansion"],"answer":"extended opening hours","explanation":"The paragraph focuses on extended opening hours. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The library now closes at eight instead of six. This is the main update in the latest local notice.","stage":"guided"},{"id":"reading_matching_headings-1","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","partial fleet replacement"],"answer":"partial fleet replacement","explanation":"The paragraph focuses on partial fleet replacement. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Electric buses replaced half the diesel fleet last year. This is the main update in the latest local notice.","stage":"guided"},{"id":"reading_matching_headings-2","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","online booking availability","The history of ticket prices"],"answer":"online booking availability","explanation":"The paragraph focuses on online booking availability. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Museum visitors can book tickets online. This is the main update in the latest local notice.","stage":"guided"},{"id":"reading_matching_headings-3","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["a fortnightly meeting","The history of ticket prices","Plans for overseas expansion"],"answer":"a fortnightly meeting","explanation":"The paragraph focuses on a fortnightly meeting. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Volunteers meet in the garden every second Saturday. This is the main update in the latest local notice.","stage":"guided"},{"id":"reading_matching_headings-4","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a six-week evening course"],"answer":"a six-week evening course","explanation":"The paragraph focuses on a six-week evening course. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The evening course runs for six weeks and starts in May. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-5","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","a weekly maintenance closure","The history of ticket prices"],"answer":"a weekly maintenance closure","explanation":"The paragraph focuses on a weekly maintenance closure. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The pool is closed on Mondays for cleaning. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-6","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["growth in cycle commuting","The history of ticket prices","Plans for overseas expansion"],"answer":"growth in cycle commuting","explanation":"The paragraph focuses on growth in cycle commuting. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"More residents cycled to work after a protected lane opened. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-7","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","relocation after weather damage"],"answer":"relocation after weather damage","explanation":"The paragraph focuses on relocation after weather damage. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The market moved indoors because rain damaged the stalls. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-8","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","local coffee purchasing","The history of ticket prices"],"answer":"local coffee purchasing","explanation":"The paragraph focuses on local coffee purchasing. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The cafe buys its coffee from two local suppliers. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-9","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["more frequent trains","The history of ticket prices","Plans for overseas expansion"],"answer":"more frequent trains","explanation":"The paragraph focuses on more frequent trains. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The new timetable reduced the wait between trains from fifteen to ten minutes. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-10","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a borrowing limit"],"answer":"a borrowing limit","explanation":"The paragraph focuses on a borrowing limit. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Students may borrow two books at a time. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-11","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","a new lakeside path","The history of ticket prices"],"answer":"a new lakeside path","explanation":"The paragraph focuses on a new lakeside path. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The park has a new walking trail around the lake. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-12","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["improved paper recycling","The history of ticket prices","Plans for overseas expansion"],"answer":"improved paper recycling","explanation":"The paragraph focuses on improved paper recycling. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Households separated more paper after receiving labelled bins. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-13","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a ticket collection deadline"],"answer":"a ticket collection deadline","explanation":"The paragraph focuses on a ticket collection deadline. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Tickets must be collected before noon on Friday. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-14","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","weekday opening times","The history of ticket prices"],"answer":"weekday opening times","explanation":"The paragraph focuses on weekday opening times. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The bakery opens at seven on weekdays. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-15","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["less time commuting","The history of ticket prices","Plans for overseas expansion"],"answer":"less time commuting","explanation":"The paragraph focuses on less time commuting. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Staff saved travel time by working from home twice a week. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-16","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a limited tour route"],"answer":"a limited tour route","explanation":"The paragraph focuses on a limited tour route. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The walking tour includes the castle but not the harbour. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-17","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","two booking methods","The history of ticket prices"],"answer":"two booking methods","explanation":"The paragraph focuses on two booking methods. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Patients can request appointments by phone or through the website. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-18","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["reduced water consumption","The history of ticket prices","Plans for overseas expansion"],"answer":"reduced water consumption","explanation":"The paragraph focuses on reduced water consumption. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Water use fell after leaking pipes were repaired. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-19","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","what the fee includes"],"answer":"what the fee includes","explanation":"The paragraph focuses on what the fee includes. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The workshop fee covers materials but excludes lunch. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-20","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","a new waiting facility","The history of ticket prices"],"answer":"a new waiting facility","explanation":"The paragraph focuses on a new waiting facility. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"A waiting room was added beside platform two. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-21","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["diversification of crops","The history of ticket prices","Plans for overseas expansion"],"answer":"diversification of crops","explanation":"The paragraph focuses on diversification of crops. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"Farmers planted more varieties to reduce dependence on one crop. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-22","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["The history of ticket prices","Plans for overseas expansion","a revised festival date"],"answer":"a revised festival date","explanation":"The paragraph focuses on a revised festival date. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The festival takes place in September, not August as first announced. This is the main update in the latest local notice.","stage":"independent"},{"id":"reading_matching_headings-23","kind":"choice","prompt":"Choose the heading covering this paragraph.","options":["Plans for overseas expansion","an exhibition of regional art","The history of ticket prices"],"answer":"an exhibition of regional art","explanation":"The paragraph focuses on an exhibition of regional art. The other headings introduce topics the paragraph does not discuss.","hint":"Compare every detail with the lesson strategy.","passage":"The gallery displays paintings by regional artists. This is the main update in the latest local notice.","stage":"independent"}]}'::jsonb,true) on conflict(skill,version) do nothing;
insert into skill_lab_private.lessons(skill,module,version,content,published) values ('listening_distractors','listening',1,'{"skill":"listening_distractors","module":"listening","title":"Follow corrections","outcome":"Keep the final confirmed detail.","trap":"The first detail may be corrected later.","strategy":"Listen for correction signals such as actually, instead and sorry. Replace the earlier detail.","example":"Monday—sorry, Tuesday → Tuesday is the final answer.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":null,"items":[{"id":"listening_distractors-0","kind":"choice","prompt":"On which day will the session take place?","options":["Tuesday","Thursday","No day is confirmed"],"answer":"Thursday","explanation":"The earlier day is corrected: the final arrangement is Thursday.","hint":"Compare every detail with the lesson strategy.","transcript":"Here are the details for pottery. We first advertised Tuesday, but the session has moved to Thursday. The fee is 14 pounds, including materials. Please bring your studio.","audio":"/audio/skill-lab/listening_distractors-0.mp3","stage":"guided"},{"id":"listening_distractors-1","kind":"choice","prompt":"On which day will the session take place?","options":["Friday","No day is confirmed","Monday"],"answer":"Friday","explanation":"The earlier day is corrected: the final arrangement is Friday.","hint":"Compare every detail with the lesson strategy.","transcript":"Here are the details for photography. We first advertised Monday, but the session has moved to Friday. The fee is 26 pounds, including materials. Please bring your camera.","audio":"/audio/skill-lab/listening_distractors-1.mp3","stage":"guided"},{"id":"listening_distractors-2","kind":"choice","prompt":"On which day will the session take place?","options":["No day is confirmed","Saturday","Sunday"],"answer":"Sunday","explanation":"The earlier day is corrected: the final arrangement is Sunday.","hint":"Compare every detail with the lesson strategy.","transcript":"Here are the details for gardening. We first advertised Saturday, but the session has moved to Sunday. The fee is 18 pounds, including materials. Please bring your gloves.","audio":"/audio/skill-lab/listening_distractors-2.mp3","stage":"guided"},{"id":"listening_distractors-3","kind":"choice","prompt":"On which day will the session take place?","options":["Wednesday","Monday","No day is confirmed"],"answer":"Monday","explanation":"The earlier day is corrected: the final arrangement is Monday.","hint":"Compare every detail with the lesson strategy.","transcript":"Here are the details for history. We first advertised Wednesday, but the session has moved to Monday. The fee is 32 pounds, including materials. Please bring your notebook.","audio":"/audio/skill-lab/listening_distractors-3.mp3","stage":"guided"},{"id":"listening_distractors-4","kind":"choice","prompt":"On which day will the session take place?","options":["Tuesday","No day is confirmed","Friday"],"answer":"Tuesday","explanation":"The earlier day is corrected: the final arrangement is Tuesday.","hint":"Compare every detail with the lesson strategy.","transcript":"Here are the details for cooking. We first advertised Friday, but the session has moved to Tuesday. The fee is 21 pounds, including materials. Please bring your apron.","audio":"/audio/skill-lab/listening_distractors-4.mp3","stage":"independent"},{"id":"listening_distractors-5","kind":"choice","prompt":"On which day will the session take place?","options":["No day is confirmed","Sunday","Saturday"],"answer":"Saturday","explanation":"The earlier day is corrected: the final arrangement is Saturday.","hint":"Compare every detail with the lesson strategy.","transcript":"Here are the details for cycling. We first advertised Sunday, but the session has moved to Saturday. The fee is 45 pounds, including materials. Please bring your helmet.","audio":"/audio/skill-lab/listening_distractors-5.mp3","stage":"independent"},{"id":"listening_distractors