insert into skill_lab_private.lessons(skill,module,version,content,published) values ('writing_task1_overview','writing',1,'{"skill":"writing_task1_overview","module":"writing","title":"Write a clear overview","outcome":"Describe the main pattern without inventing a cause.","trap":"Listing every value hides the overall picture.","strategy":"Compare the start and finish, identify the main trend and contrast, and keep causes out unless shown.","example":"If rail rises and car use falls, summarise that contrast; do not invent a new transport policy.","version":1,"basic":true,"estimated_minutes":8,"open_prompt":"Practise write a clear overview. Write two or three sentences about a useful local service, applying this lesson.","items":[{"id":"writing_task1_overview-0","kind":"choice","prompt":"Choose an accurate overview of the two changes.","options":["Use of A rose, while use of B fell.","Both categories rose over the period.","A rose because prices fell."],"answer":"Use of A rose, while use of B fell.","explanation":"A increases and B decreases. No reason for either change is provided.","hint":"Compare every detail with the lesson strategy.","passage":"Travel survey 2000–2005: category A changes from 12% to 34%; category B changes from 54% to 28%.","stage":"guided"},{"id":"writing_task1_overview-1","kind":"choice","prompt":"Choose an accurate overview of the two changes.","options":["Both categories rose over the period.","A rose because prices fell.","Use of A rose, while use of B fell."],"answer":"Use of A rose, while use of B fell.","explanation":"A increases and B decreases. No reason for either change is provided.","hint":"Compare every detail with the lesson strategy.","passage":"Travel survey 2001–2006: category A changes from 13% to 35%; category B changes from 53% to 28%.","stage":"guided"},{"id":"writing_task1_overview-2","kind":"choice","prompt":"Choose an accurate overview of the two changes.","options":["A rose because prices fell.","Use of A rose, while u